import { withMachineGcode } from "./machine-gcode.ts";
import { withPrintMeta } from "./print-meta.ts";

let failed = 0;

function eq(name: string, got: unknown, want: unknown): void {
  const a = JSON.stringify(got);
  const b = JSON.stringify(want);
  if (a === b) return;
  failed += 1;
  console.error(`FAIL ${name}\n  got  ${a}\n  want ${b}`);
}

const engine = [
  "; generated by Lime Slice — FDM strategy blender",
  "; printer: Ideaformer IR3 V2",
  "; blend: single speed",
  "M140 S90",
  "M104 S250",
  "M190 S90",
  "M109 S250",
  "G21",
  "G90",
  "M82",
  "G28",
  "G92 E0",
  ";LAYER:0 Z:0.200 H:0.200 ",
  "G1 X10 Y10 E0.1",
  ";LAYER:1 Z:0.400 H:0.200 ",
  "G1 X11 Y10 E0.2",
  ";LAYER:2 Z:0.600 H:0.200 slow ×0.50",
  "G1 X12 Y10 E0.3",
  ";LAYER:3 Z:0.800 H:0.200 ",
  "G1 X13 Y10 E0.4",
  "G1 Z10.800 F600",
  "M106 S0",
  "M104 S0",
  "M140 S0",
  "; bed 250x250 mm nozzle 0.40 mm",
  "; TIME:66342.7s FILAMENT_MM:182315.07 FILAMENT_G:556.919 ARCS:0",
  "M84",
  "",
].join("\n");

const when = new Date(2026, 9, 9, 13, 39, 25);
const base = { now: when, version: "1.0.0" };
const meta = {
  ...base,
  layerSeconds: [600, 1800, 1800, 1800],
  layerHeight: 0.2,
  nozzleDiameter: 0.4,
  filamentType: "ABS",
};
const m73 = (text: string) => text.split("\n").filter((line) => line.startsWith("M73"));

const out = withPrintMeta(engine, meta);
const lines = out.split("\n");

eq("the first line names the slicer, version, and local export time", lines[0], "; generated by Lime Slice 1.0.0 on 2026-10-09 at 13:39:25");
eq("the blender name keeps its own comment line", lines[1], "; FDM strategy blender");
eq("the rest of the header stays", lines.slice(2, 4), ["; printer: Ideaformer IR3 V2", "; blend: single speed"]);

eq("M73 follows the layer line where the percent changes", lines.slice(lines.indexOf("G92 E0"), lines.indexOf("; bed 250x250 mm nozzle 0.40 mm")), [
  "G92 E0",
  ";LAYER:0 Z:0.200 H:0.200 ",
  "M73 P0 R100",
  "G1 X10 Y10 E0.1",
  ";LAYER:1 Z:0.400 H:0.200 ",
  "M73 P10 R90",
  "G1 X11 Y10 E0.2",
  ";LAYER:2 Z:0.600 H:0.200 slow ×0.50",
  "M73 P40 R60",
  "G1 X12 Y10 E0.3",
  ";LAYER:3 Z:0.800 H:0.200 ",
  "M73 P70 R30",
  "G1 X13 Y10 E0.4",
  "G1 Z10.800 F600",
  "M73 P100 R0",
  "M106 S0",
  "M104 S0",
  "M140 S0",
]);

eq("the footer carries what Moonraker reads, before the final M84", lines.slice(lines.indexOf("; bed 250x250 mm nozzle 0.40 mm")), [
  "; bed 250x250 mm nozzle 0.40 mm",
  "; TIME:66342.7s FILAMENT_MM:182315.07 FILAMENT_G:556.919 ARCS:0",
  "; estimated printing time (normal mode) = 18h 25m 43s",
  "; filament used [mm] = 182315.07",
  "; filament used [g] = 556.92",
  "; total layers count = 4",
  "; layer_height = 0.2",
  "; nozzle_diameter = 0.4",
  "; filament_type = ABS",
  "M84",
  "",
]);

const slivers = withPrintMeta(engine, { ...base, layerSeconds: [30, 30, 3540, 3600] });
eq("a layer that keeps the same percent adds no M73", m73(slivers), ["M73 P0 R120", "M73 P50 R60", "M73 P100 R0"]);
eq("values the app does not know add no footer line", slivers.split("\n").filter((line) => /^; (layer_height|nozzle_diameter|filament_type)/.test(line)), []);
eq("remaining minutes round up", m73(withPrintMeta(engine, { ...base, layerSeconds: [61, 1, 1, 1] }))[0], "M73 P0 R2");

const bare = withPrintMeta(engine, { ...base, layerSeconds: [] }).split("\n");
eq("no layer times means no M73", m73(bare.join("\n")), []);
eq("no layer times still writes the header and the time", [bare[0], bare.includes("; estimated printing time (normal mode) = 18h 25m 43s")], ["; generated by Lime Slice 1.0.0 on 2026-10-09 at 13:39:25", true]);
eq("a layer count that does not match the markers adds no M73", m73(withPrintMeta(engine, { ...base, layerSeconds: [1, 2, 3] })), []);

const tiny = (time: string) => withPrintMeta(`; generated by Lime Slice — FDM strategy blender\n; TIME:${time}s FILAMENT_MM:1.00 FILAMENT_G:0.003 ARCS:0\nM84\n`, { ...base, layerSeconds: [] });
eq("short times drop the leading units", tiny("125.4").includes("; estimated printing time (normal mode) = 2m 5s\n"), true);
eq("a day shows", tiny("90061.0").includes("= 1d 1h 1m 1s\n"), true);

eq(
  "no TIME line, no estimate lines",
  withPrintMeta("; generated by Lime Slice — FDM strategy blender\nG28\nM84\n", { ...base, layerSeconds: [], layerHeight: 0.2 }),
  "; generated by Lime Slice 1.0.0 on 2026-10-09 at 13:39:25\n; FDM strategy blender\nG28\n; layer_height = 0.2\nM84\n",
);

// The printer's start and end blocks go in after this, so M73 P100 stays ahead of the end block.
const withBlocks = withMachineGcode(out, "PRINT_START", "PRINT_END", { startOwnsHoming: true });
const code = withBlocks.split("\n").filter((line) => !line.startsWith(";") && line !== "");
eq("the start block is still the first G-code", code[0], "PRINT_START");
eq("the end block follows M73 P100", code.slice(code.indexOf("M73 P100 R0"), code.indexOf("M73 P100 R0") + 3), ["M73 P100 R0", "PRINT_END", "M106 S0"]);

// The patterns Moonraker's PrusaSlicer reader applies, as JavaScript.
const identify = /; generated by (.+?) on \d{4}-\d{2}-\d{2} at \d{2}:\d{2}:\d{2}/.exec(out);
eq("Moonraker identifies the slicer from the header", identify?.[1], "Lime Slice 1.0.0");
const timeLine = /;\sestimated\sprinting\stime.*/.exec(out)?.[0] ?? "";
const part = (unit: string) => Number(new RegExp(`(\\d+)${unit}`).exec(timeLine)?.[1] ?? 0);
eq("Moonraker reads the estimated time", part("d") * 86400 + part("h") * 3600 + part("m") * 60 + part("s"), 66343);
eq("Moonraker reads the filament length", Number(/filament\sused\s\[mm\]\s=\s([0-9]*\.?[0-9]+)\n/.exec(out)?.[1]), 182315.07);

if (failed > 0) {
  console.error(`${failed} failed`);
  throw new Error(`${failed} failed`);
}
console.log("print-meta tests passed");
